'use strict';
const test=require('node:test'),assert=require('node:assert/strict');

// Inspect the form values generated by the real UI component without launching
// a browser or introducing a DOM framework. This does not establish visual QA.
const decode=value=>value.replace(/&(quot|#39|amp|lt|gt);/g,(_,key)=>({quot:'"','#39':"'",amp:'&',lt:'<',gt:'>'}[key]));
function form(html) {
  const rows=[...html.matchAll(/<fieldset data-scope-row="(\d+)">([\s\S]*?)<\/fieldset>/g)].map(([,index,body])=>{
    const fields=new Map();
    for(const [tag] of body.matchAll(/<input [^>]*>/g)) {
      const attribute=tag.match(/(data-import-[\w-]+)(?:="([^"]*)")?/);
      if(!attribute)continue;
      const [,name,key]=attribute;
      fields.set(`[${name}${key===undefined?'':`="${key}"`}]`,{
        value:decode(tag.match(/value="([^"]*)"/)?.[1] || ''),checked:/\schecked(?:\s|>)/.test(tag),
      });
    }
    for(const [,name,selectBody] of body.matchAll(/<select (data-import-[\w-]+)>([\s\S]*?)<\/select>/g)) {
      const options=[...selectBody.matchAll(/<option value="([^"]*)"([^>]*)>/g)].map(([,value,attributes])=>({value:decode(value),selected:/\bselected\b/.test(attributes)}));
      fields.set(`[${name}]`,{options,value:(options.find(option=>option.selected) || options[0]).value});
    }
    return {dataset:{scopeRow:index},querySelector:selector=>fields.get(selector)};
  });
  return {rows,querySelectorAll:()=>rows};
}
function plan() {
  return {proposed:{access_services:[]},rows:[0,1].map(index=>({index,supplied:{journal:'Biometrics'},
    status:'unresolved',service_status:'unresolved',messages:[],candidates:index===0?[
      {name:'Biometrics',issn:'0006-341X',eissn:'1541-0420'},
      {name:'Biometrics',issn:'0006-341X',eissn:'0090-5364'},
    ]:[]}))};
}

test('Import renders distinct full-pair candidates and submits either selected pair',async()=>{
  const {renderImportRows,readImportChoices}=await import('../../frontend/ui/research-scope-import.js');
  for(const eissn of ['1541-0420','0090-5364']) {
    const identity={issn:'0006-341X',eissn};
    const rendered=form(renderImportRows(plan()));
    const select=rendered.rows[0].querySelector('[data-import-candidate]');
    assert.equal(new Set(select.options.map(option=>option.value)).size,3);
    const value=select.options.find(option=>JSON.parse(option.value || 'null')?.eissn===eissn).value;
    select.value=value;
    const choices=readImportChoices(rendered);
    assert.deepEqual(choices['0'].candidate,identity);
    const updated=form(renderImportRows(plan(),choices));
    assert.equal(updated.rows[0].querySelector('[data-import-candidate]').value,value);
  }
});

for(const method of ['manual','carsi'])test(`Import keeps an explicit ${method} correction through two Update Previews`,async()=>{
  const {renderImportRows,readImportChoices}=await import('../../frontend/ui/research-scope-import.js');
  const p=plan(),url='https://library.example.org/journals';
  p.rows[0].supplied={journal:'Biometrics',service:'Library','access method':method,'access url':url};
  let choices={'0':{service:'Library','access method':method,'access url':url}};
  for(let update=0;update<2;update++) {
    const rendered=form(renderImportRows(p,choices));
    rendered.rows[1].querySelector('[data-import-field="journal"]').value=`Another Journal ${update}`;
    choices=readImportChoices(rendered);
    assert.equal(choices['0']['access method'],method);
    assert.equal(choices['0'].service,'Library');
    assert.equal(choices['0']['access url'],url);
  }
});
